const cartBadge=document.querySelector(".cart-badge");const cartList=document.getElementById("cartList");const cartTotalLabel=document.getElementById("cartTotal");const checkoutButton=document.getElementById("checkoutButton");const siteHeader=document.querySelector(".site-header");const menuToggle=document.querySelector(".menu-toggle");const mobileMenu=document.querySelector(".mobile-menu");function getCartItems(){try{return JSON.parse(localStorage.getItem("shopEaseCart")||"[]")}catch{return[]}}function setCartItems(items){try{localStorage.setItem("shopEaseCart",JSON.stringify(items))}catch{}}function updateCartCount(){const count=getCartItems().reduce((total,item)=>total+item.quantity,0);if(cartBadge){cartBadge.textContent=String(count)}}function formatPrice(value){return`$${value.toFixed(2)}`}function calculateCartTotal(cart){return cart.reduce((sum,item)=>sum+item.price*item.quantity,0)}function renderCartItem(item,index){const optionLines=item.options&&Object.keys(item.options).length?`<p class="cart-item-options">${Object.entries(item.options).map(([key,value])=>`${key.replace(/Select$/,"")}: ${value}`).join(" • ")}</p>`:"";return`
        <article class="cart-item" data-index="${index}">
            <div class="cart-item-image">
                <img src="${item.image||"data:image/svg+xml;charset=UTF-8,%3Csvg%20width%3D%22150%22%20height%3D%22150%22%20xmlns%3D%22http%3A//www.w3.org/2000/svg%22%3E%3Crect%20width%3D%22150%22%20height%3D%22150%22%20fill%3D%22%23f7f9fc%22/%3E%3C/svg%3E"}" alt="${item.title}" loading="lazy" />
            </div>
            <div class="cart-item-body">
                <div class="cart-item-top">
                    <div>
                        <h3>${item.title}</h3>
                        ${optionLines}
                        <p class="cart-item-price">${formatPrice(item.price)}</p>
                    </div>
                    <button class="remove-item" type="button">Remove</button>
                </div>
                <div class="cart-item-controls">
                    <div class="quantity-control">
                        <button type="button" class="quantity-decrease">−</button>
                        <input type="number" min="1" value="${item.quantity}" aria-label="Quantity for ${item.title}" />
                        <button type="button" class="quantity-increase">+</button>
                    </div>
                    <p class="cart-item-subtotal">Subtotal: ${formatPrice(item.price*item.quantity)}</p>
                </div>
            </div>
        </article>
    `}function renderCart(){const cart=getCartItems();if(!cart.length){cartList.innerHTML=`
            <div class="cart-empty">
                <p>Your cart is currently empty.</p>
                <a class="primary-button" href="index.html">Continue shopping</a>
            </div>
        `;checkoutButton.disabled=true;cartTotalLabel.textContent="$0.00";updateCartCount();return}cartList.innerHTML=cart.map((item,index)=>renderCartItem(item,index)).join("");cartTotalLabel.textContent=formatPrice(calculateCartTotal(cart));checkoutButton.disabled=false;updateCartCount()}function updateCartItem(index,quantity){const cart=getCartItems();const item=cart[index];if(!item)return;quantity=Number(quantity)||1;if(quantity<1)quantity=1;item.quantity=quantity;setCartItems(cart);renderCart()}function removeCartItem(index){const cart=getCartItems();cart.splice(index,1);setCartItems(cart);renderCart()}function initializeCartActions(){cartList.addEventListener("click",event=>{const itemElement=event.target.closest(".cart-item");if(!itemElement)return;const index=Number(itemElement.dataset.index);if(event.target.matches(".quantity-decrease")){const input=itemElement.querySelector('input[type="number"]');updateCartItem(index,Number(input.value)-1)}if(event.target.matches(".quantity-increase")){const input=itemElement.querySelector('input[type="number"]');updateCartItem(index,Number(input.value)+1)}if(event.target.matches(".remove-item")){removeCartItem(index)}});cartList.addEventListener("input",event=>{if(!event.target.matches('input[type="number"]'))return;const itemElement=event.target.closest(".cart-item");if(!itemElement)return;const index=Number(itemElement.dataset.index);updateCartItem(index,event.target.value)});if(checkoutButton){checkoutButton.addEventListener("click",()=>{window.location.href="checkout.html"})}}function initializeCartNavigation(){const cartButton=document.querySelector(".cart-button");if(cartButton){cartButton.addEventListener("click",()=>{window.location.href="cart.html"})}}function initializeMobileMenu(){if(!menuToggle||!siteHeader||!mobileMenu)return;menuToggle.addEventListener("click",()=>{const isExpanded=siteHeader.classList.toggle("nav-open");menuToggle.setAttribute("aria-expanded",isExpanded.toString());menuToggle.setAttribute("aria-label",isExpanded?"Close navigation":"Open navigation");mobileMenu.setAttribute("aria-hidden",(!isExpanded).toString())})}window.addEventListener("DOMContentLoaded",()=>{initializeMobileMenu();initializeCartNavigation();initializeCartActions();renderCart()});